import { test } from 'node:test';
import assert from 'node:assert/strict';
import { createCapture } from '../../src/checkout/capture.js';
import { createSandboxGateway } from '../../src/gateway.js';

test('an order is charged and marked paid', async () => {
  const gateway = createSandboxGateway();
  const capture = createCapture(gateway);
  const order = { id: 'o-1', total: 1200 };
  const receipt = await capture(order);
  assert.equal(order.paid, true);
  assert.equal(receipt.amount, 1200);
  assert.equal(gateway.charges.length, 1);
});

test('a paid order is not charged again', async () => {
  const gateway = createSandboxGateway();
  const capture = createCapture(gateway);
  const order = { id: 'o-2', total: 800 };
  await capture(order);
  await capture(order);
  assert.equal(gateway.charges.length, 1);
});

// Issue #43: the pay button can be pressed twice before the first charge has finished.
test('a second call while the first is still running does not charge again', async () => {
  const gateway = createSandboxGateway();
  const capture = createCapture(gateway);
  const order = { id: 'o-3', total: 1500 };
  const [first, second] = await Promise.all([capture(order), capture(order)]);
  assert.equal(gateway.charges.length, 1);
  assert.equal(second, first);
  assert.equal(order.receipt, first);
});

test('two different orders paid at the same time are both charged', async () => {
  const gateway = createSandboxGateway();
  const capture = createCapture(gateway);
  const [a, b] = await Promise.all([capture({ id: 'o-4', total: 300 }), capture({ id: 'o-5', total: 400 })]);
  assert.equal(gateway.charges.length, 2);
  assert.notEqual(a.id, b.id);
});

test('an order whose charge failed can be paid again', async () => {
  let calls = 0;
  const gateway = {
    async charge(orderId, amount) {
      calls += 1;
      if (calls === 1) throw new Error('gateway down');
      return { id: 'ch_1', orderId, amount };
    },
  };
  const capture = createCapture(gateway);
  const order = { id: 'o-6', total: 900 };
  await assert.rejects(capture(order), /gateway down/);
  assert.notEqual(order.paid, true);
  const receipt = await capture(order);
  assert.equal(receipt.id, 'ch_1');
  assert.equal(calls, 2);
});

